{"file_path": "/tmp/analyze.py", "content": "from rdkit import Chem

# Product SMILES
product_smiles = "Cc1c(C(=O)Nc2ccc(-c3nc(Br)cnc3N)cc2)c(=O)n(-c2ccccc2)n1C"
mol = Chem.MolFromSmiles(product_smiles)

if mol:
    print(f"Product valid: {Chem.MolToSmiles(mol)}")

    # Find the biaryl bond between phenyl and pyrimidine
    # Look for the connection point
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AROMATIC:
            begin = bond.GetBeginAtomIdx()
            end = bond.GetEndAtomIdx()
            begin_ring = mol.GetAtomWithIdx(begin).GetRingInfo().NumRings()
            end_ring = mol.GetAtomWithIdx(end).GetRingInfo().NumRings()
            if begin_ring > 0 and end_ring > 0:
                print(f"Aromatic bond between ring atoms: {begin} - {end}")
